quests[31036] = { id = 31036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", completion = "I've been expecting your arrival, {name}.", objectives = "Speak with Commander Bagran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31037] = { id = 31037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Undercity.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", completion = "I've been expecting your arrival, {name}.", objectives = "Speak with Commander Bagran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31038] = { id = 31038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Snow Blossom", description = "News of your feats has been traveling around the camp, {name}.\n\nIn fact, Snow Blossom would like to test your skill in battle.\n\nYou had best prepare yourself, {class}. She is not easily defeated.\n\nIf you can prove your worth to her, you will win a valuable friend.", progress = "How did it go?", completion = "Ahhhh, so you bested Snow Blossom in battle, did you?\n\nShe will be stinging from that loss for a while, I'd wager.\n\nHowever, you have done well to win her to your side.\n\nShe does not warm to strangers quickly, but through time, she will prove to be a loyal and dependable companion.", objectives = "Challenge Snow Blossom and defeat her in the Challenger's Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31039] = { id = 31039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", completion = "The Shan'ze are up to something. Well done, {name}, but we must continue to monitor their actions.", objectives = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31040] = { id = 31040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Sprites", description = "The Darkwoods sprites on Shan'ze Dao have fallen to the mogu's domination.\n\nThe once sly tricksters are now the full servants of the Shan'ze. They grow bolder each day, stealing and killing to satisfy their masters.\n\nThey must be eliminated, but be careful. They may look harmless, but they are actually quite vicious.", completion = "Good work, {class}. Left unchecked, the sprites would soon outnumber our entire army.", objectives = "Kill 30 Darkwoods Pixies or Darkwoods Charmers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31041] = { id = 31041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Rescue!", description = "Eggs. Yes, you heard me right. I said eggs, and these aren't for eating.\n\nHave you ever seen a cloud serpent egg?\n\nThese rare eggs look like jewels, and were once worth their weight in solid gold.\n\nShan'ze Dao to the north normally teems with wild cloud serpents, but the mogu and the sprites have their eggs on lock-down.\n\nWe need to save as many of these precious eggs as we can.\n\nI'm counting on YOU, {name}.", progress = "Did you find any eggs? The serpents lay their eggs in nests on the beach, but the wood sprites are also known to steal them whenever they can.", completion = "Gently, gently!\n\nThank you for recovering these eggs safely, {name}.\n\nI know a few Serpent Riders in the Jade Forest who will take good care of these.", objectives = "Collect 8 Cloudrunner Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31042] = { id = 31042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyx Hearts", description = "The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they also create their own dark creatures from stone, metal, blood, and ancient sorcery.\n\nTheir creations, the Onyx Stormclaws, guard the island to the northwest.\n\nI wish to study the magic binding these creatures. Bring me their hearts, so that I can better understand what sorcery we are up against.", progress = "The Onyx Stormclaws will never disobey their masters.", completion = "These will do well, {name}. Thank you.", objectives = "Collect 4 Onyx Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31043] = { id = 31043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Arts", description = "It is said that Shan'ze Dao was once home to a great mogu temple.\n\nThere, the Shan'ze studied and practiced the art of subjugating the dead or inanimate.\n\nMuch of their knowledge still remains on the island to the northwest, buried among the ruins.\n\nWe need to get our hands on their knowledge - both to keep it out of their hands, and to understand the nature of their experiments.", progress = "Knowledge is powerful. That is why the mogu are so dangerous.", completion = "Well done, {name}.\n\nWe'll begin deciphering the writing on these tablets at once.", objectives = "Collect 8 Shan'ze Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31044] = { id = 31044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronze Claws", description = "Among the Shan'ze's fiercest and most loyal creations are their quilen.\n\nThese beasts will hunt until they kill their prey, or die in the process.\n\nI need you to not only cull their numbers, but also to retrieve their bronze claws.\n\nTheir claws are strong and razor sharp, and we can use them to make weapons and hooks for our cause.", progress = "The quilen are fierce, but I see fierceness in your eyes as well.", completion = "These claws will come in handy.\n\nGood work, {class}.", objectives = "Collect 20 Bronze Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31045] = { id = 31045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusions Of The Past", description = "{class}, I need your strength to eliminate the Shan'ze Illusionists on Shan'ze Dao, to the northwest.\n\nIt wearies me to ask of you this difficult task.\n\nThe illusionists are among the strongest of the Shan'ze's elite sorcerors.\n\nThey will not be easy to defeat, but I know no {class} who is better suited to the task.", progress = "Do not be fooled by their illusions.", completion = "I knew you could do this, {name}!\n\nWith fewer Shan'ze Illusionists to stand against us, our task here will be much easier.", objectives = "Kill 3 Shan'ze Illusionists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31046] = { id = 31046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Hatchlings", description = "I have seen the cruel experiments that the Shan'ze are performing on their island to the northwest.\n\nThe Shan'ze raise baby serpents from the egg. They keep the young in tiny cages, surrounded by squalor and filth.\n\nThe cruelest gaolers starve and torture them.\n\nWe must save as many hatchlings as we can. You have my full permission to punish any mogu that gets in your way!", completion = "Those creatures will remember you as their savior.\n\nYou have done well, {name}.", objectives = "Free 20 Cloudrunner Hatchlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31047] = { id = 31047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Born Free", description = "Do you know the story of the great cloud serpents of Pandaria, {name}?\n\nSomeday you must hear it. Unfortunately, there is no time to tell it now.\n\nWhat you must know is that the wild cloudrunner serpents of Townlong are in trouble.\n\nThe mogu are capturing wild serpents and corrupting their minds, bending them to their sinister will.\n\nGo to Shan'ze Dao, to the northwest. Free the adult serpents from their chains. Save them!", completion = "Good work, {race}. It gladdens me to see that the wild serpents are free once again.", objectives = "Free 6 Wild Cloudrunners from their chains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31048] = { id = 31048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Consequences", description = "We've found ancient mogu burial urns among the ruins on Shan'ze Dao.\n\nThis is normally no problem, except these urns are home to angry mogu spirits.\n\nNot only do these urns pose a danger to anyone unlucky enough to find one, but they could be used for destruction if they were to fall into the wrong hands.\n\nWe must rid Shan'ze Dao of their presence.", progress = "Did the spirits cause you any problems?", completion = "Good riddance, I say! Those mogu ghosts were long past their expiration.", objectives = "Kill 24 Shan'ze Ancestors. Shan'ze Ancestors may be found inside Mogu Burial Urns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31049] = { id = 31049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sprite Of Everything", description = "The sprites of Shan'ze Dao have always been capricious tricksters, but now they have fallen under the mogu's influence.\n\nEven as we speak, they gather under a new leader.\n\nWe cannot allow this to happen.\n\nTheir mischievous pranks were one thing, but united, their dark magic is too powerful and too dangerous to comprehend.\n\nTake out their leader before it is too late.", progress = "The sprites are easily manipulated, and too dangerous to ignore.", completion = "Good work, {name}.\n\nThe wood sprites may look harmless, but that's what makes them so dangerous.", objectives = "Kill the Darkwoods Faerie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31050] = { id = 31050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chose Fire Mage" }
quests[31051] = { id = 31051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chose Frost Mage" }
quests[31052] = { id = 31052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chose Priest" }
quests[31053] = { id = 31053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Started Shado-Pan Dailies" }
quests[31054] = { id = 31054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocked Yalia Sagewhisper" }
quests[31055] = { id = 31055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between a Saurok and a Hard Place", completion = "Before your research, I don't think pandarens ever really knew why the saurok were so vicious. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring Between a Saurok and a Hard Place to Lorewalker Cho.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31058] = { id = 31058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Funky Monkey Brew", description = "Pirates! Our shores have been scoured by the most ill-tempered, ill-mannered, ill-hygienic, and ill-good hozen that ever was found in Pandaria. And to make matters worse, they claim to serve the legendary Captain Ook!\n\nWe see them every night partying and brewing punch on their island Unga Ingoo.\n\n I say we take their brew for a change! I think I can even improve their mix.\n\nGather up some friends and meet me on the southern side of Unga Ingoo. It is time for a Brew Run!", progress = "These hozen pack some mean toys and some meaner brews.", completion = "A fine punch! A fine punch indeed! The sort of punch that punches back. Well done, {class}!", objectives = "Defeat Captain Ook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31060] = { id = 31060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawson test POI" }
quests[31061] = { id = 31061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Storm", description = "Shan Bu, the leader of the Shan'ze, is performing some kind of dark ritual at the summit of the island to the northwest.\n\nWe believe that the subjugated Shan'ze Cloudrunners are powering the spell. How, we still do not know.\n\nWe believe that the Shan'ze Cloudrunners can still be saved from the corruption that taints them.\n\nTake these bronze claws. Use them to mount the back of a Shan'ze Cloudrunner.\n\nAttack them. Beat some sense back into their heads!", progress = "How did it go?", completion = "We do not fully understand what the Shan'ze are doing, or the nature of their domination over the wild serpents.\n\nBan's theory is that the only thing that can cut through the mind control is physical pain.\n\nOnce the Shan'ze Cloudrunners feel enough pain, it looses the corruption's hold, and they finally remember who they are.", objectives = "Use the Bronze Claws to mount 8 Shan'ze Cloudrunners. Attack them to free them of their corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31062] = { id = 31062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When The Dead Speak", description = "The Shan'ze's experiments are overseen by a powerful necromancer known as a Shan'ze Deathspeaker.\n\nIf we are to put an end to their operations, we must eliminate their leader.", progress = "What would possess the mogu to perform such hideous experiments?", completion = "Excellent work, {name}.\n\nI expected nothing less.", objectives = "Kill the Shan'ze Deathspeaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31063] = { id = 31063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Chin and Serevex", description = "Lao-Chin is facing off against the leader just above the entrance in the tree, on the north side of Sik'vess. He is to bring back the second crystal that we need to get into the mantid tunnel.\n\nGo there and lend him your aid.", completion = "We have the second crystal then. Good.", objectives = "Kill Serevex with the aid of Lao-Chin the Iron Belly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31064] = { id = 31064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurong and Rothek", description = "Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the last mantid leader cannot escape.\n\nCatch up with him and help him kill the mantid leader. Nurong will bring back the final crystal once you've aided him in this.", progress = "Act swiftly. I do not want the Sha of Hatred to escape our grasp again.", completion = "The final crystal is ours. We are on the doorstep of our final confrontation.", objectives = "Kill Rothek with the aid of Hawkmaster Nurong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31065] = { id = 31065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Beneath", description = "Taoshi set up a spyglass on the ridge edge to show me what her scouting uncovered.\n\nGo over and take a look.", progress = "Go. Look.", completion = "Our tasks lay before us.", objectives = "Look through the spyglass in Rensai's Watchpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31066] = { id = 31066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry From Darkness", description = "So, you survived the imperial clutches. You are... resilient.\n\nThe Klaxxi hear another paragon to the north, among the sha-scorched roots of Kypari Vor.\n\nThis one cries out in terror and agony. It cannot be saved.\n\nThe Klaxxi want him put down. Go and defeat him or do not return here.", progress = "The order stands. Slay the fallen paragon.", completion = "What?! How did you...\n\nThe Deathcaller was a legendary hero. He must not have been fully wakened.\n\nYou are fortunate.", objectives = "Slay the corrupted paragon at Kypari Vor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31067] = { id = 31067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heavens Hum With War", description = "The mantid don't ever make my job easy, but now they've gone too far.\n\nWe can fend off the occasional attack from Kor'vess, but now... now they're starting to surround us. What's worse, they're draining the amber from our tree.\n\nThis will not stand! We need that amber! To make beer!\n\nThey've dug a burrow into the south side of the tree. I'm short-handed here. Could you take care of them for me?", progress = "Azzix, his name was. I think. Azzix K'tai.", completion = "We're not here to hurt anybody. We just want to make a little bit of brew out of this tree sap. Is that too much to ask?", objectives = "Slay Azzix K'tai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31068] = { id = 31068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Recipe", description = "\"When the horror comes a-rising\nAnd the heavens hum with war\nOur great vessel of salvation\nMust be broken from its core.\"\n\nThe scroll continues on for several stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic message.", progress = "Is that some sort of scroll?\n\nWould you mind if I took a look?", completion = "<Lya reads the entirety of the message.>\n\nThis scroll, this... this prophecy...\n\nIt's terrifying!", objectives = "Bring the Scroll of Auspice to Lya of Ten Songs at The Sunset Brewgarden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31069] = { id = 31069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound With Shade", description = "About that scroll you found...\n\nI keep looking at that line in the second stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me.\n\nI must admit, I've often considered taking some of the area's residual sha essence and incorporating it into a brew. I suspect that this is the shade which our recipe calls for.\n\nYou will find large amalgamations of sha to the southeast of our tree... though you may also be able to harvest some from the local wildlife.", completion = "Beautiful. This will make a fine addition to our brew.\n\nThe most dangerous ingredients are quite often the most delicious.", objectives = "Harvest 100 drops of Shade by slaying sha creatures and wildlife near The Sunset Brewgarden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31070] = { id = 31070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggers of the Great Ones", description = "That recipe said: \"rending daggers of the great ones\"...\n\n<Olon ponders this line.>\n\nMushan! That's it!\n\nThere's plenty of mushan roaming out there with these great, big teeth... they're as long as daggers. That's gotta be what the recipe calls for.", progress = "I wonder how we'll mix those things into the brew? Can't grind them up - that'd be too gritty.\n\nMaybe I'll just soak 'em for a while.", completion = "I never thought of putting mushan teeth in a brew before.\n\nThat scroll's got some wacky ideas.", objectives = "Obtain 3 Large Mushan Teeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31071] = { id = 31071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Bring Us Great Shame", description = "I have failed my fellow brewers.\n\nI took some supplies out to the clearing, east of our tree... and I left them there. Now, with the sha corrupting the land, and the mantid on the prowl, it is too dangerous for me to bring them back.\n\nIf you would help me look for them, perhaps I could regain some of my lost honor.", progress = "Did you find them? Can it be?", completion = "You have brought me joy, traveler.", objectives = "Find the Lost Keg, the Lost Mugs, and the Lost Picnic Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31072] = { id = 31072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rending Daggers", description = "Forget about them, and forget their BREW. We've got real work to do.\n\nThe scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where to find them.\n\nA pair of mantid lieutenants patrol the Horrid March, to the south. Each one carries a ceremonial dagger.\n\nBring those daggers back here, {name}. We may be on the brink of something big.", progress = "I think I'm starting to understand the next few lines of this prophecy, {name}.\n\nDo you have the daggers yet?", completion = "These daggers, look!\n\n<Lya holds the blades hilt-to-hilt.>\n\nThey were built to fit together! But how to join them...?", objectives = "Obtain the Blade of Kz'Kzik and the Blade of Ilikkax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31073] = { id = 31073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound With Wood", description = "<Vu eyes the recipe.>\n\nHmm... \"bound with wood\". We don't typically brew with wood. Sap, yes... but not wood.\n\nWe have, on rare occasions, infused our drinks with corewood from the treants to the west of here. Most of them have fallen to the mantid... but their remains should suffice for our recipe.", progress = "We don't brew with wood here. It gives the brew a harsh, insipid flavor, not unlike that of wine.\n\n<Vu spits.>", completion = "I'll get these pieces prepared.\n\nWe've already gathered quite a few of these ingredients! I'll have to get a pot boiling soon.", objectives = "Obtain 8 pieces of Fragrant Corewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31074] = { id = 31074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wood and Shade", description = "\"Rending daggers of the great ones shall be bound with WOOD and SHADE.\"  Hmm.\n\nI've learned a lot about the Kor'thik mantid in my time here. I know that they maintain shrines within their settlement, Kor'vess.\n\nOne is a heartroot of the very tree that they inhabit. The other is a dark pillar, connecting them with their queen.\n\nThese shrines are the wood and shade. If my predictions are right... the daggers should react in their presence.", completion = "{name}, look! The daggers - they've bound together, into a forked blade.\n\nWe are on the right track. I knew this wasn't a beer recipe.", objectives = "Find the Mark of the Empress and the Heartroot of Kypari Kor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31075] = { id = 31075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunset Kings", description = "Olon had a clever idea. He thinks that we should visit the sprites to the west, and ask them if they have any of these ingredients. Some of the elements to this recipe are seeming... strange.\n\nThe Rikkitun sprites have a village to the west of Kor'vess. I hope to see you there, {name}.", completion = "It's been a while since I brewed on the road.", objectives = "Meet Sapmaster Vu at Rikkitun Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31076] = { id = 31076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Stormstouts", description = "Greetings, {race}. I am Chen Stormstout.\n\nI'm looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through here? Would you mind helping me ask around?", progress = "You are brave to have come across the wall, {race}.", completion = "<Chen listens intently.>\n\nBig Dan, Han, Evie, and Mama. I understand.\n\nIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.\n\nTravel well, {name}, and follow the Wanderer's Way.", objectives = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31077] = { id = 31077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evie Stormstout", description = "I was too late. She was so small... and I was too late.\n\nShe should be given a proper burial. A little warrior like her deserves better than this.", progress = "<Chen is in mourning.>", completion = "<Chen is, for the moment, silent.>", objectives = "Meet Chen Stormstout at The Sunset Brewgarden, then listen to his eulogy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31078] = { id = 31078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Han Stormstout", description = "There will be time for mourning later. For now, there are other Stormstouts to be found.\n\nThey say that Han Stormstout was last seen exploring Kor'vess. I suspect he headed into that mantid burrow, just across the way.\n\nYou should meet me down there, {name}. I don't doubt that I can handle a few mantid by myself... but I'd feel better with you by my side.", progress = "I think I see someone over there, but I can't seem to get across these amber beams.", completion = "First Evie, now Han.\n\nI was too late again.", objectives = "Find Han Stormstout in the Morrowchamber beneath Kor'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31079] = { id = 31079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horror Comes A-Rising", description = "We are protected from the mantid. Such was the agreement made so many millennia ago.\n\nThere are forces from which we are not safe, however. The kyparites beneath the ground to the west will haunt us, chase us... even eat us. The mistlurkers eat our kind by the handful.\n\nHelp our people, outsider. Defeat our enemies.", progress = "We hate being eaten.", completion = "It is good to have someone of your colossal size in our village.\n\nYou have many uses.", objectives = "Slay 7 Shuffling Mistlurkers and 2 Kyparites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31080] = { id = 31080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Wings", description = "I think that old paper said something about \"fiery wings.\" Those little dragons around here have wings. They're kind of fiery, in a way.\n\nYou're quicker than me. Try catching some of those dragons... or at least slapping the powder off of them.\n\nNo point in killing a harmless little dragon, if all you want is the sparkle from their wings.", progress = "I haven't been able to catch any of those things!", completion = "YEAH!!! FLITTERLING DUST!!!\n\n<Olon throws the powder into the pot.>\n\nThis brew is turning out... strange, and pretty smelly. I'm starting to think maybe Lya was right.", objectives = "Slap Rikkilea Flitterlings, then catch 88 flecks of Flitterling Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31081] = { id = 31081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incantations Fae and Primal", description = "I suspect we are going to need the help of these sprites.\n\nWe have two enchanted daggers, bound together with wood and shade. Now we need someone to perform ancient \"incantations\" on our artifact.\n\nBefore we ask for favors, let's show the sprites that we mean well. I heard their leader talking about a pair of mistlurkers that kidnapped several of their villagers. If we slay these fog beasts... we may get the \"incantation\" we need in return.", progress = "I hope we're on the right track...", completion = "Nice work. I've heard the sprites talking about us.\n\nWe're getting their attention.", objectives = "Slay Ahgunoss and Mygoness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31082] = { id = 31082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Vessel of Salvation", description = "I know what you and the girl-panda seek. We can perform the rite for you... in time.\n\nFirst, I require aid. The seeds fall from our great mother-tree. It is our responsibility to collect them, even in dangerous times like these.\n\nEscort my chanters to the motherseeds, that they may bring them back to the collection pit.", progress = "The collection pit is down the hill, just to the west of here.", completion = "Yes, good. The motherseeds are taken care of.\n\nNow, we may speak of your enchantment.", objectives = "Bring 3 Motherseeds to the collection pit in Rikkitun Village, with the assistance of the Rikkitun Chanters.\n\nYou can use the Rikkitun Bell to re-summon your chanters if you become separated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31083] = { id = 31083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promises of Gold", description = "As soon as the creature died, a strange group of sprites appeared and took its pearl away.\n\nThe sprites have a village nearby, called Rikkitun Village. Perhaps you should investigate.", completion = "This shinyseed... it was your doing? I already had one shinyseed... but two is better.\n\nWe need only the seed, not the casing. If you like, you can keep.", objectives = "Report to Chief Rikkitun at Rikkitun Village in Dread Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31084] = { id = 31084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bind the Glamour", description = "It has been a very, very long time since our tribe has been called on to perform this rite. I will do the best I can.", progress = "...", completion = "The blade is prepared.\n\nNow, only one task remains: you must use it.", objectives = "Allow Chief Rikkitun to enchant the Forked Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31085] = { id = 31085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fires and Fears of Old", description = "We've found the blades, bound them together with wood and shade, and blessed them with an ancient incantation. If I'm not mistaken, it's time to use this thing.\n\nThe sprites spoke of an ancient piece of sap within the Amber Hibernal, a mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the prophecy spoke of.\n\nWhatever's inside that sap must be important. Good luck, {name}.", progress = "Make sure to bring that forked blade with you.", completion = "There was a... a mantid inside that amber? I never would have thought that the solution to our war on the mantid would be... another mantid.\n\nThere are still many things that I have left to learn, but I do know this: that CERTAINLY wasn't a beer recipe.", objectives = "Use the Ruining Fork on Iyyokuk the Lucid, then protect him until he is able to escape.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31086] = { id = 31086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Ancients", description = "Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the sap from the great trees of the area. I should know - I brew with the stuff all the time.\n\nThe most ancient tree of all is the one that Grand Empress Shek'zeer calls her home, now known as the Heart of Fear. Find some amber from that tree, and our brew should be complete.", progress = "Any luck?", completion = "That should do it! Recipe... complete.\n\nNow let's see how this beer tastes.", objectives = "Obtain a Chunk of Solidified Amber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31087] = { id = 31087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extending Our Coverage", description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been silent for many years. It must sing; The Klaxxi demand it!\n\nThis time I will go with you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.", progress = "Why are you just standing here?", completion = "It is good you showed up when you did.\n\nPerhaps you are not as useless as I thought...\n\nThe Klaxxi'va sing to the paragon now. Soon they will know where to send you. For now there are other tasks.", objectives = "Activate the Resonating Beacon in Amberglow Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31088] = { id = 31088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crime and Punishment", description = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken.\n\nThe Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters.", completion = "The Klaxxi are pleased with our work, outsider. You have proven to be more resourceful than we thought.", objectives = "Kill 8 Ik'thik Harvesters on the Stinging Trail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31089] = { id = 31089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Sea, Nevermore", description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall into their scaly hands.\n\nYou will find him; you will awaken him. Do not return without him!\n\nIf you do this The Klaxxi will be pleased with us.", completion = "What... what sort of creature are you?\n\nHow have you awoken me?", objectives = "Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31090] = { id = 31090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better With Age", description = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises!\n\nGather the young amber. We will store it until it is aged and can be consumed.", progress = "I would go with you to gather amber, but my talents are more useful here.", completion = "Even this raw amber will be of use. We can't afford to be picky in times like these.\n\nThe Klaxxi'va will be glad I thought of this. I will tell them you helped!", objectives = "Gather 7 Amber-Filled Jars from the Amber Collectors on the Stinging Trail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31091] = { id = 31091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunited", description = "You look at me and see I am no great warrior. Why was I chosen to be a Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance alone.\n\nBefore I explain further, I need to know that you are trustworthy.\n\nSomething precious to me was hidden at the time of my preservation. I am nothing without it.\n\nDefend me as I unearth my greatest weapon, and you will have my trust.", completion = "Kovok is just as impressive as the last time I saw him. He will ensure great victories for the Klaxxi.", objectives = "Assist Kaz'tik the Manipulator as he unearths his greatest weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31092] = { id = 31092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed or Be Eaten", description = "After years of working with the Kunchong I developed a theory; raising one from infancy would strengthen the bond and therefore strengthen the sonic connection.\n\nI had just begun training Kovok when I was chosen for encasement. He is still very young and will need diligent training to reach his full potential.\n\nI'm entrusting Kovok to you, but be warned; if any harm comes to him your life is forfeit.\n\nFirst, you must feed him to gain his trust. The turtles in the area should be suitable for this.", progress = "Once the bond is formed a Kunchong will gladly give its life for you.", completion = "Very good! I had half expected Kovok to just eat you. What a pleasant surprise to see you both in one piece,\n\nPerhaps Kunchong raising is in your blood.", objectives = "Begin Kovok's training by feeding him 6 Succulent Turtle Filets found on the Brineshell Snappers in the Briny Muck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31093] = { id = 31093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen in the Mist", completion = "Hozen are, by their very nature, a rambunctious lot.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring Hozen in the Mist to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31094] = { id = 31094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Tales", completion = "This is a real treat. I always did enjoy the jinyu. Such a peaceful people with a real appreciation for wisdom.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring Fish Tails to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31095] = { id = 31095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Heart of the Mogu", completion = "Mogu. Even the word makes my fur stand on end. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring The Dark Heart of the Mogu to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31096] = { id = 31096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What is Worth Fighting For", completion = "Who would have thought the freedom of the pandaren people would begin with a single punch.\n\n Wonderful. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring What is Worth Fighting For to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31097] = { id = 31097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Mantid Swarm", completion = "When we began this research project I never thought I would learn so much about such a terrifying people.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring Heart of the Mantid Swarm to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31098] = { id = 31098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Founding of the Order of the Cloud Serpent", objectives = "Bring Founding of the Order of the Cloud Serpent to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31099] = { id = 31099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klaxx Attack", objectives = "Bring Klaxx Attack to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31100] = { id = 31100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Song of the Yaungol", completion = "The yaungol are a warring people strengthened by their exile beyond the wall. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring The Song of the Yaungol to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31101] = { id = 31101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legends of the Brewfathers", objectives = "Bring Legends of the Brewfathers to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31102] = { id = 31102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seven Burdens of Shaohao", completion = "This is a story I have long sought to uncover. Ever since the Sha was released I have felt in my belly that this tale was at the heart of it all.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring The Seven Burdens of Shaohao to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31103] = { id = 31103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ballad of Liu Lang", completion = "The long lost story of Lou Lang and his Wandering Isle. This is a superb addition to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring The Ballad of Liu Lang to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31104] = { id = 31104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Yalia Sagewhisper", description = "The Shado-Pan brothers and sisters continue to whisper of your deeds, {name}.\n\nIn fact, Yalia herself has taken quite an interest in your studies.\n\nShe wishes to challenge you in the training ring.\n\nYou would do well to impress her. If you do, she just may be willing to help you in the future.", progress = "Did you speak to Yalia?", completion = "You did it! You bested Yalia!\n\nYou have most definitely earned her favor, {race}.", objectives = "Challenge Yalia Sagewhisper and defeat her in the Challenger's Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31105] = { id = 31105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", completion = "The Shan'ze are up to something. Well done, {name}, but we must continue to monitor their actions.", objectives = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31106] = { id = 31106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", completion = "The Shan'ze are up to something. Well done, {name}, but we must continue to monitor their actions.", objectives = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31107] = { id = 31107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Citizens of a New Empire", description = "At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a totem of horror.\n\nLike those outside of the palace, the clutch nearby is now used to corrupt our swarmborn.\n\nRecover the eggs of the Vor'thik before they are tainted. We shall raise them here. They will be the citizens of a new empire, free from the sha.", progress = "Kypari Vor was beautiful once. Rich with amber and surrounded by prime hunting grounds.", completion = "They are large. They will hatch soon.\n\nGood. We may need them.", objectives = "Gather 10 Vor'thik Eggs from Kypari Vor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31108] = { id = 31108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concentrated Fear", description = "Amber is power. It brings life.\n\nThis... dread amber you brought me has been twisted. It is concentrated fear.\n\nThe Vor'thik know this well. Their kypari has been completely engulfed by sha, and they use the dread amber to quicken their own swarmborn.\n\nBring me the crystals used by the Vor'thik fear-shapers in their rituals. The Klaxxi will study them and decide on a protocol for disposal.", progress = "Do you have the crystals?", completion = "What would happen, I wonder, if you ate one? What would it do to your soft, pink insides?", objectives = "Gather 4 Dread Amber Foci from Vor'thik Fear-Shapers at Kypari Vor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31109] = { id = 31109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Swarm", description = "The Empress continues to amass her forces. Without intervention, they WILL overrun that wall - even if it means smothering it in the corpses of a million swarmborn.\n\nLet us find a better place for those corpses.\n\nLet me know when you are ready to depart for the clutches - I will gladly drop you in from above.", progress = "We must kill faster than they can multiply. It is that simple.", completion = "This will do, for now.", objectives = "Slay 40 Shek'zeer Mantid in the Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver for an air-drop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31110] = { id = 31110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Portal", description = "Ah, just the {class} I wanted to see!\n\nWe've finally figured out why the portal is not working. We need more arcane powder!\n\nIt would take us months to get a shipment sent out to us, but luckily, the mogu on this island carry plenty for their own spells.\n\nThey tend to use some older stuff, so we're going to need a lot of it.", progress = "Did you find the powders?", completion = "Excellent! Excellent!\n\nThis is just the stuff, {name}.\n\nWe'll get to work right away. I have no doubt we'll be done very soon.", objectives = "Collect 1000 Ancient Arcane Powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31111] = { id = 31111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eradicating the Zan'thik", description = "The warriors of Zan'vess are some of the most feared and respected in the empire, for good reason.\n\nImpalers are unmatched in their mastery of the polearm - no doubt Malik trained among the Zan'thik in his time. Their manipulators command terrifying sonic power with the ease and subtlety of a breath.\n\nBoth will need to be dealt with.", completion = "I will admit, Wakener, I am impressed.", objectives = "Kill 6 Zan'thik Impalers and 6 Zan'thik Manipulators in Zan'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31112] = { id = 31112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're So Thorny!", description = "The crate, once full of desperately needed supplies, has been thoroughly pillaged.\n\nA quick scan of the area shows evidence left behind by the thieves. Icy thorns, just like the ones on the water sprites on the shoreline to the east.\n\nThis is a life or death situation for your band of survivors. Those supplies need to be retrieved from these thieving pests and returned to camp.", progress = "You manage to get your hands on them supplies, pal?", completion = "Look at that!\n\nThese supplies should keep us kickin' for a few more days.\n\nAnd my boots! Ya managed not to blow 'em up. Way ta go, {name}!", objectives = "Collect 5 Emergency Supplies from the Water Sprites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31113] = { id = 31113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault Fire Camp Gai-Cho", description = "The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to the northeast, conspired with the Osul yaungol in their recent incursion into Kun-Lai.\n\nWe cannot allow such an incursion to go unpunished.\n\nGo, attack Fire Camp Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and threaten The Ox Gate again.", progress = "Is your raid on Gai-Cho complete?", completion = "Well - that should certainly deter any attack for a while. Good work, {name}.", objectives = "Kill 16 Gai-Cho Yaungol, Earthtalkers or Pitchthrowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31114] = { id = 31114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault Deadtalker's Plateau", description = "We have always left the Deadtalkers alone. For so long, they were just responsible for maintaining the sacred burial grounds of the yaungol tribes.\n\nNow, though, they are practicing dark magic, defiling the corpses of their former clanmates... \n\nI know not where they learned those dark magics, or why they no longer treat their dead with respect, but we do not have time to find out. \n\nWe need to stop them.", progress = "Have you defeated the Deadtalkers?", completion = "By conspiring to use these dark magics, the Deadtalkers have given up their rights to protection. Your actions should deter them from their current course, I hope.", objectives = "Kill 8 Deadtalker Corpsedefilers and 1 Deadtalker Crusher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31115] = { id = 31115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Freed Han" }
quests[31116] = { id = 31116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Dust", description = "The spirits that the Yaungol are entrapping from the remains of their ancestors still have a bit of the essence of life within them. \n\nIf you defeat the spirits in battle, you can collect essence from the spirits as dust, and then return it to the corpses in the area, which will send the spirits, finally, to the next life.\n\nThis is the only way to set right what the Deadtalkers have done. It will also help keep us safe.", completion = "Good, you have helped right this terrible wrong.", objectives = "Return 8 spirits to their remains at the Deadtalker Plateau in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31117] = { id = 31117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uruk!", description = "Uruk is the Deadtalker of the Townlong yaungol. Your mission will not be truly complete until you defeat him. Go to it!", progress = "How goes the mission?", completion = "Uruk is dead! This threat has subsided, at least for today. Thank you, {name}.", objectives = "Kill Uruk at Deadtalker's Plateau in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31118] = { id = 31118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadtalker Cipher", description = "We need to understand what went wrong with the Deadtalkers. \n\nFor so many years, the Deadtalkers were simply responsible for maintaining the burial grounds and holding funerals for fallen warriors.\n\nFrom a recent raid, we've recovered a tablet from the grounds that is clearly written using a cipher, but it isn't one we've encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we can begin to put together the cypher and understand what's happened.", progress = "Did you find something?", completion = "Aha! Show me that.\n\nHmm... we will send this to the monastery for analysis. As we find which of these symbols are most common in their writing, we can begin to understand the meaning of these writings.", objectives = "Collect a Scroll of Spiritbinding Rites from the yaungol at Deadtalker's Plateau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31119] = { id = 31119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy... Is Still My Enemy!", description = "The mantid are our enemies. As are the yaungol at Fire Camp Gai-Cho.\n\nIt is fortunate, then, that they are also each other's enemies. Mantid from Kri'vess constantly attack the Gai-Cho yaungol, who hold them off at their front gates.\n\nI want you to wreak havoc. \"Borrow\" some highly explosive oil barrels from camp Gai-Cho, and toss them down onto the battlefield from the air.\n\nI don't care which ones you kill, just kill a lot of them.", progress = "How goes the battle?", completion = "Ha! Good work. Teaches both of them to make enemies of the Shado-Pan.", objectives = "Use Highly Explosive Yaungol Oil Barrels to kill 100 mantid or yaungol on the Gai-Cho Battlefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31120] = { id = 31120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheng Bo!", description = "Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in their operations, you now have an opportunity to strike a major blow. \n\nSlay the Warbringer!", progress = "How goes the assualt?", completion = "With Cheng Bo subdued, we can refocus our efforts on our other enemies. Your efforts earn you much respect, {name}.", objectives = "Kill Cheng-Bo at Fire Camp Gai-Cho in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31121] = { id = 31121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stay a While, and Listen", description = "Rush rush rush - are your people always in such a hurry?\n\nSit and have some tea with me a moment, and we will discuss your plight.\n\n<Lorewalker Cho's features settle into a patient smile.>", progress = "I hope I didn't bore you, traveler.", completion = "I will help you, traveler, but first I would like to learn a little about this Horde of yours...", objectives = "Drink from Cho's Teapot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31122] = { id = 31122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chose Prot Warrior" }
quests[31123] = { id = 31123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chose Arms Warrior" }
quests[31124] = { id = 31124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chose Brewmaster" }
quests[31125] = { id = 31125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocked Chao" }
quests[31126] = { id = 31126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocked Lao-Chen" }
quests[31127] = { id = 31127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Chao the Voice", progress = "Well? How did it go?", completion = "I'm sure there's no hard feelings. She just loves a good fight.\n\nYou should talk to her next time I have some missions for you. She's quite an able fighter, as I'm sure you saw.", objectives = "Challenge Chao the Voice, and then defeat her in combat at Shado-Pan Garrison in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31128] = { id = 31128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Lao-Chin the Iron Belly", description = "Lao-Chin seems to have his head in the clouds... or, rather, in his beer.\n\nAfter all of his recent battles, he seems completely obsessed with with trying to develop the perfect brew for fighting. \n\nThat's well and good, but we need him to actually do some fighting!\n\nYou should go challenge him, see if you can snap him out of his rut. \n\nIf you beat him, he'll probably want to go out and help fight just to try to one-up you!", progress = "Well?", completion = "Wow, you must have impressed Lao-Chin. He can't stop talking about how excited he is to go out and fight with you. Good work.", objectives = "Challenge Lao-Chen the Iron Belly and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31129] = { id = 31129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Stormstouts", progress = "You are brave to have come across the wall, tauren.", completion = "<Chen listens intently.>\n\nBig Dan, Han, Evie, and Mama. I understand.\n\nIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.\n\nTake care, {name}.", objectives = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31130] = { id = 31130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit with Lorewalker Cho", description = "Stranger, I may be able to help you find your prince. But first, I would like to know a little more about you and your people.\n\nCome, help me with my chores, and we will chat.\n\nYou have the look of a grizzled war veteran, but certainly you have a few minutes to help a bookish Pandaren like myself putter around the house, yes?", progress = "There is nothing like a little manual labor to bring strangers together, don't you think?", completion = "Despite your many years of combat, you've still got an eye for beauty, {name}. I like that about you!\n\nNow, let's find this missing prince of yours.", objectives = "Befriend Lorewalker Cho by assisting him around his house: Trim his tree, paint his wall, and feed his birds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31131] = { id = 31131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitepetal Lake", description = "Reports suggest that things are quiet at Whitepetal Lake today, but I've dispatched Ren Firetongue and He Softfoot to make sure it stays they way.\n\nIf you want to aid the effort further, head to the west to the lake, meet up with He, and help him keep things secure from any hostile threats.", completion = "<He Softfoot smiles at you as you approach.>", objectives = "Speak to He Softfoot at Whitepetal Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31132] = { id = 31132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mile in My Shoes", description = "Oh, where have my manners gone? Technically, I suppose I am the host here.\n\nAllow me to tell you a little bit about myself and my people before asking questions of you.", completion = "I suppose the best way to explain what a Lorewalker is all about is to show you...", objectives = "Speak to Lorewalker Cho at the Circle of Bone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31133] = { id = 31133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kor'thik Aggression", description = "I'm no brewer - just looking at all those heaps of ingredients makes my head spin. Just put the brew in front of me when it's finished, thank you.\n\nNo, I'm here to make sure that the brewers don't get cut in half while they're trying to make that perfect brew. It's not an easy job.\n\nThe Kor'thik mantid across this basin have been attacking us nightly. If you're already heading over there, why don't you return the favor and attack a few of them?", completion = "You've got the makings of a fine brewgarden guard, {race}. Let me know if you ever get tired of the whole \"{class}\" thing.", objectives = "Slay 17 Kor'thik Mantid at Kor'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31134] = { id = 31134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If These Stones Could Speak", description = "This is a very ancient place, traveler.\n\nOnly recently have I pieced together a method of translating the forgotten language carved into these stones.\n\nOh, the thrill of discovery! This never gets old, I assure you.\n\nHere, you are the guest. You do the honors. I insist.\n\nUse this key to unlock the secrets the stones contain.", progress = "Your assistance is most appreciated, traveler.", completion = "That is enough translating for one day, I think.\n\nThis experience has been an enlightening one, I hope.", objectives = "Use the Stone Monoliths at the Circle of Bone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31135] = { id = 31135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nXi, Friend of the Small has visited us from a faraway land and will help oversee your training and adjustment to life on the surface. She's waiting for you on the small practice field across the road.", completion = "Why, you look great! I've heard bad things about what happens down there.\n\nWell, are you ready to start your training in the ways of the {class}?", objectives = "Meet with Xi, Friend of the Small in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31136] = { id = 31136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Our Lines", description = "Scouts bring me reports of a powerful Imperion that slipped through our lines in the south and is now heading for the road in the eastern vale.\n\nI need someone I can trust to stop it. Find it and kill it quickly, {name}.", completion = "Well fought. I hope to see more of you soon.", objectives = "Kill General Temuja.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31137] = { id = 31137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin and the other gnomes have mentioned that memory loss is pretty common for you survivors.\n\nAnyways, High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31138] = { id = 31138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Monk", description = "When you fight, you grow in skill. As you grow in skill, you will begin to figure out new moves. Go, explore, learn, and show me what you figure out.", completion = "You picked that one up quickly. I can't wait to show you some of my other favorite tricks.", objectives = "Reach level 3 to learn Tiger Palm. Once you've learned it, use it twice at a Training Dummy in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31139] = { id = 31139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", objectives = "Kill 6 Blackrock Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31140] = { id = 31140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", progress = "Kill the spies!", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", objectives = "Kill 8 Blackrock Spies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31141] = { id = 31141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Bao, a pandaren who is visiting us from a faraway land. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, you got my letter, {name}... good.\nI've come from afar to teach your people the ways of the {class}.", completion = "I  have come from very far to train you in the ways of our people. Do not hesitate to come to me for training whenever you like.", objectives = "Read the Calligraphed Letter and speak to Bao in Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31142] = { id = 31142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Palm of the Tiger", description = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important.\n\nAs you get more experience, you'll be able to do new techniques you never thought of.\n\nGo, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", completion = "You're a quick learner, {name}.", objectives = "Reach level 3 to learn Tiger Palm, then practice using it on a Training Dummy south of the entrance to Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31143] = { id = 31143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Battle!", description = "I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!", objectives = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31144] = { id = 31144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", progress = "Kill the goblin assassins!", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", objectives = "Kill 8 Goblin Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31145] = { id = 31145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31146] = { id = 31146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scribbled Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. The pandaren visitor, Ting, sent it for you. Maybe you monks can read this garbage, but I can't. You should go talk to her. She's in the Inn across the way.", progress = "Oh, yes, I sent that for you. I hope to prove that Forsaken can learn the arts of the {class} - perhaps you can help?", completion = "Yes, you can come to me to learn more about our people and our ways, especially when it comes to the arts of the {class}.", objectives = "Read the Elegant Scroll and speak to Ting, Strong of Stomach in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31147] = { id = 31147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "As you overcome great challenges in your journey to master struggles both internal and external, you will begin to uncover new abilities hidden inside yourself. Go, now, and develop a mastery of yourself, such that you uncover the Tiger Palm technique. Then, go practice it on a training dummy.", completion = "Ah, it's my favorite pupil! I'm going to go ahead to Undercity and try to teach the way of the {class} to some of the Deathguards. You should meet up with me there.", objectives = "Reach level 3 to learn Tiger Palm, then practice using it on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31148] = { id = 31148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novice Elreth", description = "Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills.\n\nThe next time you see me, I will be in Undercity.", sourceObjective = "Speak to Novice Elreth at Deathknell in Tirisfal Glades.", sourceObjectiveStatus = "unverified-source-field" }
quests[31150] = { id = 31150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elegant Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from our visitor from afar, Lo. Take a gander at it and go find him inside Anvilmar.", progress = "I like it here, {name}. Your people have quite an appreciation for the finer things!", completion = "Well, it is good to see you. I must say, as much as you learn from me, I think I will learn from your people. Your brews are quite different than mine!", objectives = "Read the Elegant Rune and speak to Lo in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31151] = { id = 31151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, Punch, It's All in the Mind", description = "The truth is, you already have the talent and ability to learn what you need to. What I can help you do is show you where to unlock it.\n\nFirst, you must practice until you begin to understand a new technique. The first technique you learn will be the Tiger Palm. Go, learn more until you have unlocked the potential within yourself, and then practice your new move!\n\nRemember - it's all in the mind!", completion = "Ahh, good work. You may return any time you need another lesson from teacher.", objectives = "Reach level 3 to learn Tiger Palm, then use it on one of the Training Dummies outside the entrance to Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31152] = { id = 31152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peering Into the Past", description = "Just a moment, now. Allow me to gather my things.\n\nWouldn't want me to lose these notes now, would we? Especially after you risked life and limb for them!\n\nThere, all set. Let us be off, shall we?\n\nI must say, I feel much safer traveling with you after seeing how you handled that saurok!", completion = "I am most grateful for the knowledge my forebears have passed on to me.\n\nI stand upon their shoulders.", objectives = "Speak to Lorewalker Cho at the Circle of Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31153] = { id = 31153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event - Saved Diaani" }
quests[31154] = { id = 31154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event - Saved Zuulo" }
quests[31155] = { id = 31155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event - Saved Arekk" }
quests[31156] = { id = 31156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from our Pandaren friend, Gato. He visits from afar to grant us the honor of his wisdom, and to teach the ways of the monk. Do not shame your people by failing at his lessons!", progress = "Ahh, you have come.", completion = "We will honor our respective peoples by learning from each other. You will become a great {class}, if I have anything to say about it. And I will learn the ways of your people.", objectives = "Read the Calligraphed Parchment and speak with Gato in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31157] = { id = 31157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "As you walk the road of your training, you will begin to discover within yourself the power to unlock new techniques. You need not even learn them from me, or another more experienced monk - you will find that they come to you on their own.\n\nFor now, you should go and practice the basics. Gather more experience, and develop a new technique - once you have, you can practice it on the dummies nearby to master it.", completion = "Good, good. Your first challenge surpassed. We will learn much from each other, I can see.", objectives = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy and practice using Tiger Palm 2 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31158] = { id = 31158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", completion = "Not bad, mon. Ya have a natural flow to ya punches - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31159] = { id = 31159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zabrax to the east.", completion = "Anotha newblood, eh?\n\nYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Zabrax in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31160] = { id = 31160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31161] = { id = 31161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31162] = { id = 31162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Monk", description = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do.\n\nWanna see? Go, train up some, and learn someting new.\n\n'Den come back and ya can show me.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach level 3 to learn Tiger Palm. Practice using Tiger Palm against a Tiki Target.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31163] = { id = 31163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", objectives = "Report to Vol'jin at Darkspear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31165] = { id = 31165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by our Pandaren visitor, Shoyu. You should read it.", progress = "Ah, I am pleased to meet you.", completion = "I am honored that Chief Hawkwind would allow me to train you and grant you your rite of passage. While I am a master in the ways of the {class}, I am but a child in the ways of your people.", objectives = "Read the Calligraphed Note and speak to Shoyu in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31166] = { id = 31166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before.\n\nYour first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", completion = "You have done well, {name}.", objectives = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy in Camp Narache and practice using it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31167] = { id = 31167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Family Tree", description = "So there you have it, traveler, or as much of it as would make for a proper introduction, hmm?\n\nWhat of you, then? Are your people so much different than mine?\n\nSurely, there must be things we share in common. Let us see...", progress = "A fine day we're having, wouldn't you say?", completion = "Not so different, you and I.\n\nI believe we can become good friends.", objectives = "Light the Incense Bundle at the Circle of Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31168] = { id = 31168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Sigil", description = "This sigil was given to me by a messenger from our Pandaren visitor, Laoxi. It seems he would have words with you when you have a moment. Read it and bring it to him afterwards.", progress = "Ah, you have come. Good.\n\nI am learning so much - your people have a wealth of knowledge unmatched anywhere I have seen. As much as I am humbled by that fact, I hope that I may teach you of our ways, as well.", completion = "I was warned that not all of your people would be welcoming, but I have found quite the opposite - not only have I been welcomed, but I have learned so much from you.\n\nYou seem quite promising as a young {class}, and I hope I can teach you much of our ways, as your people have taught me of yours.", objectives = "Speak to Laoxi inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31169] = { id = 31169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of the Monk", description = "The true secret to the art of the monk is unlocking the knowledge and power hidden inside yourself.\n\nGo, get more experience, and learn a new skill. Then demonstrate it on one of the training dummies.", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques.", objectives = "Reach level 3 to learn Tiger's Palm. Look for a Training Dummy and practice using Tiger's Palm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31170] = { id = 31170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monk Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young monks here on Sunstrider Isle, your trainer is Pao, our Pandaren visitor.  Speak with her and see what training she has available for you.\n\nPao - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "Ah, welcome. I have been teaching your people the ways of the {class}, and they seem to be well suited for it. Perhaps you too will take to it as quickly as they.", objectives = "Speak with Pao, the Monk class trainer, inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31171] = { id = 31171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.\n\nGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", completion = "I think you've mastered the basics of the Tiger Palm technique, {name}. Perhaps you will impress me, after all.", objectives = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy outside the Sunspire and practice using it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31172] = { id = 31172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monk Training" }
quests[31173] = { id = 31173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tiger Palm", description = "I hope your people are all alright... the crash was unbelievably loud and destructive!\n\n<Mojo looks you over, evaluating your potential.>\n\nYes, you'll do fine. They've said that they need more people to fight, and they don't want me to hurt myself. I'm not afraid, but I don't want to intrude. So, I'll teach you.\n\nAs you may have discovered, your experiences in combat will unlock new potential within you. Go, see if you can master a new ability. Show it to me. You'll get the hang of things.", completion = "Keep that technique handy, {name}. You can use it to finish off strong opponents, or just to feel awesome, like a tiger.", objectives = "Reach level 3 to learn Tiger Palm. Find a Training Dummy on the northwest side of the Crash Site and practice using it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31174] = { id = 31174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Vos", description = "Another paragon calls to us..\n\nThis time, the emanations grow from The Dread Vos, an ancient lake to the south.\n\nFinding him will not be easy, for the way is guarded by our enemies.\n\nI give you this task. If you succeed, you will live.\n\nIf you fail, I will send another.", objectives = "Kill 12 Enslaved Amberdiggers or Vos'thik Slavelashers, and release the paragon, Korven the Prime.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31175] = { id = 31175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeer the Bloodseeker", description = "Our efforts to secure the shallows before Zan'vess have paid off.\n\nWe have spotted another paragon buried in amber, hidden in the waters to the southwest.\n\nAdding another paragon to our numbers is vital. Another champion from ages past could turn the tide in our favor.\n\nI would go immediately, but unfortunately, I am needed here.\n\nSince you are already a Wakener, you can carry out this task in my stead.", completion = "The hunger... they said it would be fierce, but I did not expect anything like this.\n\nIt is strange to feel so... weak.", objectives = "Awaken Skeer the Bloodseeker in the underwater cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31176] = { id = 31176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Appetite", description = "Food. I must have food.\n\nIn my time, the meat of the starfish brought not only strength, but also clarity of mind. This is what I must eat.\n\nBring this to me from the nearby shallows.\n\nWait much longer, and I will devour you instead.", progress = "The juices of the starfish will clear my mind.", completion = "Yes, give it here! Well done, Wakener.", objectives = "Collect 12 Starfish Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31177] = { id = 31177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Dining", description = "In my living years, I was the greatest warrior of the swarm.\n\nHelp me regain my strength, and I shall show you.\n\nI smell the salt sea nearby, and where you can find the sea, you will find briny clackers.\n\nBring me their tails. I must feast upon their flesh.", progress = "I have much work to do. The sooner I can fight, the sooner I can return to the Council.", completion = "Excellent. This shall give me the strength to vanquish my foes.", objectives = "Collect 8 Clacker Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31178] = { id = 31178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloody Delight", description = "A warrior is not ready for battle until he tastes the blood of his enemies.\n\nI am still too weak to hunt, so you must go in my stead.\n\nOnly the blood from the fiercest predators will do. I can smell their presence in the waters outside this cave!\n\nBring this to me, and then perhaps you shall see why they call me the Bloodseeker.", progress = "By drinking the blood of your enemies, you acquire their strength.", completion = "Yes, this will do.", objectives = "Collect 100 Volatile Blood from Dread Remoras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31179] = { id = 31179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Blood", description = "I'm afraid that I wet my hands with saurok blood while you were away.\n\nI'm sorry, but I could not help myself. Now, watch them attack me.\n\nPitiful!\n\nDo they think to take vengeance for their fallen? Do they come challenge ME?\n\nI, who have won a hundred wars? I, who stood alone against thousands and still shouted for my enemies to come?\n\nNo, these... saurok... will crumple before me like paper before the flame!\n\nI shall show you my might, Wakener. Fight alongside me and see.\n\nHere they come!", completion = "You have succeeded once again. Well done, Wakener.", objectives = "Kill 12 Muckscale Flesheaters and the Muckscale Serpentus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31181] = { id = 31181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Pots", description = "We got a load of empty crab pots out there that need fresh bait.\n\nNow, we COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it?\n\nNever gonna happen.\n\nHead to Lonesome Cove, immediately southeast, and bait those pots with two chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water.\n\nOh, and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the lingo.", progress = "What's wrong, green? You aren't afraid of the dark, icy sea are you?", completion = "Not bad, green, not bad.", objectives = "Bait 10 Empty Crab Pots in Lonesome Cove. Each pot requires 2 Sea Monarch Chunks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31182] = { id = 31182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Otter Know", description = "You know what happened to the bait in those pots?\n\nOtters. That's what happened.\n\nThey prefer fresh clams, but they'll pick our crab traps clean if they're hungry enough.\n\nThe otters in Lonesome Cove are protected by law and we run a legitimate operation here. As much as I'd love to chum those little rats and call it a day, we just make sure they aren't hungry enough to raid the crab pots.\n\nToss 'em a few clams to keep them busy while you're out there.", progress = "In the words of my old deck boss: \"Do what I say, 'cause I said it!\"", completion = "That should keep their little whiskers out of our traps for awhile.", objectives = "Use the Bag of Clams to feed 8 Coldwhisker Otters in Lonesome Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31183] = { id = 31183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Cap'n", completion = "New deckhand, eh? We'll see about that.\n\nI run a tight ship - even if she IS at the bottom of the sea.", objectives = "Speak with \"Soggy\" Su-Dao in Soggy's Gamble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31185] = { id = 31185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking Dog", description = "Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my life more than once, you know.\n\nBut I'm gettin' too old to walk him anymore, and he still needs his exercise. Take Dog for a trip around the shelf for me, would ya?\n\nHe loves to swim through the hot geysers just southeast of the shallows.\n\nHe absolutely has to... er... \"leave his mark\" on the dead whale at the far western edge of the shelf.\n\nOh, and he'll want to visit our old shipwreck, too. He likes to reminisce.", completion = "How did it go? I hope he didn't cause too much trouble!", objectives = "Take Dog to visit the hot geysers, the whale corpse, and the wreck of the Mist-Hopper on the Shelf of Mazu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31186] = { id = 31186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dog Food", description = "<Dog whines as best as a lion seal can, feebly lifting one flipper toward his massive jaws.\n\nHe's hungry.\n\nThe Shelf of Mazu is covered in rockshell makrura that should make a fine meal for him.>", progress = "<This has got to be the most pathetic lion seal you've ever seen.>", completion = "<Dog licks his chops happily, looking satisfied.>", objectives = "Help Dog to eat the remains of 10 Rockshell Snapclaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31187] = { id = 31187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Crab", description = "I just got word that a string of pots we dropped this morning hit it BIG. We're on the crab!\n\nProblem is, the rips are getting stronger and we lost track of some of the pots. They're just sitting out there, filled with spiky blue GOLD!\n\nI need you back out there. Hook one of these buoys up to any of the full traps you find and send it to the surface for us.", completion = "Nice work out there!", objectives = "Attach a Mist-Hopper Buoy to 8 Full Crab Pots on the Shelf of Mazu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31188] = { id = 31188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Week", description = "Crabbing is our big money-maker, but we send all kinds of goods back around the wall. Oils, plants, even rare minerals - the sea's bounty is rich out here!\n\nRight now the big craze in the markets back home is thresher teeth. Apparently they make great necklaces?\n\nThreshers are all over the Shelf of Mazu to the west. Bring me lots of teeth!", progress = "Having actually seen someone eaten by a thresher, I'm not sure why you'd willingly string their teeth around your neck, but whatever.", completion = "Those are perfect, just put them down over there. I'd rather not touch them myself. Creeps me out.", objectives = "Collect 200 Thresher Teeth by pulling them from the jaws of Longfin Threshers on the Shelf of Mazu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31189] = { id = 31189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reeltime Strategy", description = "I never thought I'd see the day, but for the first time since... well, EVER, Master Angler Ju Lien asked for some help with his lines.\n\nApparently the sea is going crazy today and he can't keep up. See if you can give him a hand. He's fishing just south of here.", progress = "Go give Ju Lien a hand, would ya?", completion = "What happened out there?! I heard a scream and next thing I know these nasty things come rolling in on the next wave!", objectives = "Assist Master Angler Ju Lien in Soggy's Gamble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31190] = { id = 31190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mariner's Revenge", description = "I'm not gonna sit in a damn rocking chair while my crew gets devoured by a leviathan!\n\nCome on, let's get to the dock and launch a dinghy. I got a special one set up just for this kind of situation. My own little Mist-Hopper Jr.\n\nWe'll give that thing a case of harpoon fever.", progress = "Let's go!", completion = "Nice shooting out there!\n\nI knew we could do it. Never met anything that can't be killed with enough harpoons.", objectives = "Launch the Mist-Hopper Jr. from the dock in Soggy's Gamble and use it to bring down Jiao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31194] = { id = 31194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slitherscale Suppression", description = "The Slitherscale take orders from their leader, the Slitherscale Lizard-Lord. He can be found celebrating his victories on the southeastern corner of Windward Isle.\n\nIf we can destroy this leader, we can deal their tribe a great blow.\n\nWithout their lord, the Slitherscale will think twice before attacking the gentle cloud serpents of the east.", progress = "A snake without a head cannot strike.", completion = "Wonderful! I knew you could triumph against the Slitherscale lord.", objectives = "Kill the Slitherscale Lizard-Lord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31195] = { id = 31195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ooked the Dooker" }
quests[31196] = { id = 31196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sra'vess Wetwork", description = "The mantid outnumber us quite badly. Hundreds of them for each of us.\n\nAnd, they surround us on two sides - at Gao-Ran in the south we're holding them off, but to the west, on the island they call Sra'vess, they continue to mass unabated.\n\nWe're not stupid. We're not going to launch a full scale attack on them. We can't sustain an intense battle on multiple fronts.\n\nInstead, we're going to send you, and one of our Wu Kao, to do some dirty work. Sounds fun, doesn't it?", progress = "The mission isn't complete, {name}.", completion = "Good work. I think it's always best to strike while they're unprepared.", objectives = "Kill any 15 non-elite mantid near Sra'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31197] = { id = 31197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bigger They Come...", description = "Killing the smaller mantid works mostly as a distraction. It forces them to replenish their numbers before they consider any serious offensive.\n\nThe big ones, though - we kill a few of those, and we really disrupt operations on the island. That buys ourselves a substantial amount of time. With mantid, it's like their size is directly proportional to their importance in the empire.\n\nSo kill some of the big ones for me, while you're out there.", progress = "I don't think you're done yet.", completion = "Well done, well done. That should keep us safe for a few days, at least.", objectives = "Kill any 4 elite mantid at Sra'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31198] = { id = 31198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Morale Victory", description = "The mantid have statues built on Sra'vess. We don't know exactly what they use them for. They may have some sort of religious significance, or maybe they assist with their sonic communication.\n\nWhen you fight your opponent, you don't just engage them physically, you also engage them mentally. Whatever they use them for, the fact is that those statues are important to them.\n\nWhich is why I want you to blow them up. Losing something important will be a substantial hit to morale.", progress = "The statues?", completion = "I'm sure they'll be upset without those statues. Right?", objectives = "Destroy the Southern, Central, Eastern and Western Idols at Sra'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31199] = { id = 31199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Siege Weapons!", description = "The mantid don't just attack in swarms. \n\nThey're smart. They use alchemy, bombs... and what's worst, they've got siege weapons. Those have the potential to be incredibly destructive if they attack with them.\n\nWe've got reports that they're building up a force of siege weapons to the west at Sra'vess. Go and destroy them.", completion = "Those siege weapons won't be a problem. They may rebuild, but we've bought ourselves some time.", objectives = "Destroy the four mantid siege weapons at Sra'vess in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31200] = { id = 31200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fumigation", description = "Our alchemists have cooked up a set of gas bombs that will discourage mantid from staying anywhere that we set them off. \n\nIf we plant these in the critical structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay any action from the mantid there for days.\n\nGet to it, {name}.", progress = "Have you planted the gas bombs?", completion = "Nice, I can see the smoke from here. That should definitely cause some confusion!", objectives = "Plant Shado-Pan Gas Bombs within the 5 targeted structures on Sra'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31201] = { id = 31201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends, Not Food!", description = "Our scouts have sent a very troubling report. \n\nThree of our trainees have gone missing, and our scouts found them... \n\nThey've been captured by the mantid and sent to their Kunchong pits. \n\nTheir Kunchong FEEDING pits. We're lucky that the Kunchong don't eat that often.\n\nI need you to get in there, give them these escape kites, and get them out!", progress = "The trainees, {name}! You have to save them!", completion = "Oh, thank goodness. I was worried about them!", objectives = "Rescue a Shado-Pan Trainee in each of the north, central and south Kunchong feeding pits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31203] = { id = 31203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target of Opportunity: Sra'thik Swarmlord", progress = "We need to take down the Swarmlord!", completion = "I heard you did a little... extra credit while you were out there. Good work, friend.\n\nCome back another day - I'm sure we'll have some more work for you.", objectives = "Kill the Sra'thik Swarmlord at Sra'vess in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31204] = { id = 31204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target of Opportunity: Sra'thik Hivelord", description = "Near the ocean, on the eastern side of Sra'vess, there is a cavern that leads to a network of caves.\n\nFrom there, the Sra'thik Hivelord maintains Sra'vess and plots against us. If we manage to take him out, we'll disrupt their operations for days.\n\nLet's go to it.", progress = "We've got to kill the Hivelord.", completion = "Well done, {name}! Because you took on that extra work, you've bought us some respite from the mantid.\n\nI'm sure I'll have more work for you in the future, though. Come back later.", objectives = "Defeat the Sra'thik Hivelord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31205] = { id = 31205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalker Cho Tracking Quest" }
quests[31206] = { id = 31206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31207] = { id = 31207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena of Annihilation", description = "Ah, I can still remember running fights out of a muddy hole in the ground back in Nagrand. We've come a long way, eh, Wodin?\n\nI tell you, there's nothing more these Tiger monks like than a good scrap. So much so that they've paid good coin for me to set up shop here and help draw the strongest fighters from all around!\n\nSo how about it? You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, big prizes!", progress = "What are you waiting for? The monks are spoiling for a good show.", completion = "Gurgthock said you he'd make it worth your while, kid. Take your pick!", objectives = "Enter and complete the Arena of Annihilation scenario. Afterwards, collect your reward from Wodin the Troll-Servant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31208] = { id = 31208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomous Intent", description = "If we are to strike against the Empress, we must arm ourselves with weapons. My own choice of weapon is of a particularly toxic design.\n\nThe scorpions wandering the ledge produce a deadly venom that they store in their tails.\n\nBring me their stingers, and I will show you how I earned the title of paragon.", progress = "Did you feel the venomtail's sting? Such lovely pain.", completion = "Well done, Wakener. I hope you handled these stingers carefully.\n\nThe natural poison from these scorpions is deadly, but slow.", objectives = "Collect 8 Venomous Stingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31209] = { id = 31209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Wings, Dark Things", description = "I require another ingredient to create my first poison, Wakener.\n\nThis ingredient you can easily find on the scarabs nearby.\n\nKill them and bring me their wings.", progress = "Scarab wings can be crushed to produce a very fine white, deadly powder.", completion = "Yes, excellent, Wakener! These are perfect.\n\nHave you ever considered learning the poisoner's craft?", objectives = "Collect 150 Scarab Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31210] = { id = 31210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shade of Dread", description = "The last ingredient is perhaps the deadliest.\n\nThe dreadshade flower grows all along these hills.\n\nIt is by eating these poisonous plants that the local wildlife has become so venomous.\n\nA single drop of dreadshade nectar can stop a kunchong's heart.\n\nGo and bring me some of these flowers. Do not be tempted to taste them.", progress = "Sometimes, the most beautiful things are also the most dangerous.", completion = "Many would not know the value of what you hold.\n\nYou have done well, Wakener.", objectives = "Collect 8 Dreadshade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31211] = { id = 31211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Poisoned Mind", description = "Before we return to Klaxxi'vess, I wish to look upon the empire.\n\nThe Klaxxi Council told me that the enemy gathers outside the Empress's palace.\n\nMy poisons are ready. What better way to announce my return than with death and destruction?\n\nJust be careful not to mix the two serums... at least not while you're holding the vessels.\n\nSpeak to me when you are ready to fly.", progress = "Fight from above.", completion = "Thank you for returning me home, Wakener, but I fear the war has just truly begun.", objectives = "Speak to Xaril the Poisoned Mind. Kill 200 mantid and 3 kunchong while flying with him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31212] = { id = 31212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Chose Tenwu" }
quests[31213] = { id = 31213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Chose Taoshi" }
quests[31214] = { id = 31214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Chose Nurong" }
quests[31216] = { id = 31216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Skies", description = "The swarm begins, Wakener! The mantid amass at the Heart of Fear.\n\nAlready they fill the skies with their wings and rend the earth with their claws. They shall not stop the dark march until their bodies are laid open and bleeding upon the ground.\n\nThis we shall gladly do. We will attack them from above. While I fly, use my poisons to destroy their advance.\n\nDo not mix the two serums until you are ready to attack. The reaction can be quite... violent.\n\nSpeak to me when you are ready to go.", progress = "Such wonderful destruction!", completion = "Well done, Wakener. You have a destroyer's aim.", objectives = "Kill 200 Mantid and 3 Kunchong or Dread Behemoths while flying with Xaril the Poisoned Mind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31218] = { id = 31218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Unlocked Tenwu" }
quests[31219] = { id = 31219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Unlocked Nurong" }
quests[31220] = { id = 31220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Hawkmaster Nurong", description = "You've really been building up respect with the Shado-Pan, {name}.\n\nNurong's interested in trying out his skills against you.\n\nThe good news is, if you win, I'll allow him to go with you on your missions.\n\nThe bad news is, I really don't think you'll win.", progress = "Not up to the challenge? I understand.", completion = "Well, well, well. Looks like I was wrong.\n\nGood work. Nurong's looking forward to accompanying you on your missions.", objectives = "Challenge Hawkmaster Nurong, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31221] = { id = 31221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Tenwu of the Red Smoke", description = "So... you've been challenged by the infamous Tenwu of the Red Smoke.\n\nThat's what he calls himself, at least. He's a good fighter, and a good rogue, but it's a wonder he manages to sneak up on anyone with how loudly he brags about himself.\n\nAnyways, I think you should answer the challenge. Maybe it'll give him a touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go with you on your missions. \n\nAnd I get some entertainment.", completion = "Wow! Well done. Glad to see you fought so well.\n\nMaybe if he's trying to keep up with your fighting it'll help keep his mouth shut.", objectives = "Challenge Tenwu of the Red Smoke, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31228] = { id = 31228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophet Khar'zul", description = "Prophet Khar'zul is a powerful caster, but he is also underestimating your abilities.\n\nKhar'zul and his forces must be destroyed to protect this village. His death will send a strong message to the Thunder King that we will not be defeated!\n\nYou'll find him on the Isle of Reckoning.", progress = "Is Khar'zul dead?", completion = "These events should be learned from, {name}.\n\nIt is important that we learn from our history. Had we paid attention to the histories, we may have been able to head this off before it got this far.\n\nEverything that has happened was already foretold, we just didn't know how to read it.", objectives = "Defeat Prophet Kharzul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31230] = { id = 31230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Dawn's Blossom", description = "Cho's off on another one of his adventures, and this one requires a big order of jade. I'm going to have to call in some favors.\n\nHow 'bout in the meantime you introduce yourself to some of the locals.\n\nKai Wanderbrew is a good guy to know, as is Master Windfur. Oh, and say hi to Peiji Goldendraft up at the inn.\n\nBetween the three of them, you should get the feel for life in Dawn's Blossom.", progress = "Any luck?", completion = "Good, good, good. You're going to fit right in.", objectives = "Speak with Kai Wanderbrew, Master Windfur, and Peiji Goldendraft in Dawn's Blossom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31231] = { id = 31231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadspinner Extermination", description = "Back in Gurthani Terrace where you found me, dreadspinners continue to occupy the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched swarm.\n\nEradicate those spiders and offer some relief to the archers on that wall.", completion = "I never liked spiders. Filthy, mindless insects.", objectives = "Slay 8 Dreadspinner Tenders in the Terrace of Gurthan. Speak with Kil'ruk the Wind-Reaver for an air-drop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31232] = { id = 31232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Empire", description = "My brothers speak of an ancient mogu empire that once dwelled in the ruins to the east.\n\nOnce, this tribe knew untold secrets of sorcery and subjugation.\n\nI have a curious mind, Wakener, and I wish to learn of the empires that ruled after my time.\n\nKnowledge of the past will determine our future.\n\nGo search the ruins for their ancient tablets. I will study their secrets and make them our own.", progress = "What knowledge do you bring?", completion = "Good, Wakener. It will take me time to decipher these tablets, but all knowledge is worthy.", objectives = "Collect 8 Gurthani Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31233] = { id = 31233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sap Tapping", description = "I found a grove of young amber trees to the east, Wakener.\n\nI've placed tapping devices on these trees, but I have been too busy to retrieve the sap.\n\nI need someone to find the extractors. Activate them, then bring me samples of the amber.", progress = "These trees are still young. They are not yet kypari.\n\nTheir sap is like water, while the sap of a true kypari tree is like wine.\n\nThey must be allowed to grow.", completion = "Ah yes, this is exactly what I needed.\n\nI will examine these samples. We must continue to monitor the health of these young kypari.", objectives = "Collect 6 Amber Sap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31234] = { id = 31234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting An Eye Out", description = "Ah! Wakener! You must help me! (You will help me, or else I will help myself to you!)\n\nI need more materials for my experiments, yes yes! (Blood and guts, hearts and brains, tongues and eyes, eyes, eyes!)\n\nTo the west, I have seen creatures of mist and fog. They possess such big, round, wonderful globes! Big for seeing, round and unblinking!\n\nGo now, little Wakener. Bring me back a single pristine eye!", progress = "Ooooh, what wonderful, tasty parts have you brought me?", completion = "Yes, yes! Wonderful! Oh, so delicious!", objectives = "Collect 1 Pristine Mire Beast Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31235] = { id = 31235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nope Nope Nope", description = "I recovered this weapon on a recent scouting run near the wall. It would seem ideal for helping your Shado-Pan with their infestation problem in Gurthani Terrace.\n\nThe more they are focused on keeping spiders off the wall, the less time they are killing fear-gripped swarmborn.", completion = "A crude weapon, but it has its uses.", objectives = "Use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in Gurthani Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31237] = { id = 31237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debugging the Terrace", description = "If this Empress is truly possessed by fear and paranoia, she will have sent scouts to every corner of the land in order to cement her control.\n\nThese scout grubs are likely everywhere, but difficult to spot with the naked eye. Better to track them by the pheromone trails they leave behind.\n\nI've already... gifted you... a reactive toxin that will reveal these trails to you for a brief time after experiencing the thrill of victory.\n\nGo now to the Terrace of Gurthan and root out these spies.", progress = "Best not to ask how I afflicted you with the toxin - you have become quite useful to us, and it would be a shame if we drove you mad with horror just yet.", completion = "Information is power, {name}. We cannot allow the Empess to monitor our movements.", objectives = "Stomp out 6 Eyes of the Empress around the Terrace of Gurthan. Killing anything will grant you Pheromone Tracking, helping you detect them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31238] = { id = 31238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brain Food", description = "Kovok is growing at an accelerated rate, but his brain may not be able to keep up. He'll require a special diet to ensure that he does not outgrow the capacity to control his own body.\n\nMushan tongue is rich in the nutrients that promote brain growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we feed Kovok only mushan tongues every couple of days or so, it should balance out his growth.\n\nGreatback mushan graze the hills east of here, near the Gurthani Terrace.", progress = "Have you found a suitable meal for Kovok?", completion = "Kovok was whining the whole time you were away. It was really quite pathetic.", objectives = "Bring 4 Mushan Tongues to Kaz'tik the Manipulator at Klaxxi'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31239] = { id = 31239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in a Name Name?", description = "So, you wanna be a hozen. Huh, wikket?\n\nHozen defend their lands from enemies, like jinyu.\n\nKah Kah fought many jinyu fights, and won them all.\n\nHozen only give name name to good grookers. Go grook jinyu and maybe they call you {name} {name}.\n\nJinyu creepin' down by the river. Ook 'em in the dooker!", completion = "Ha ha! Wikket Grooked ookin' Jinyu!", objectives = "Kill 7 Riverstride Jinyu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31240] = { id = 31240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai Infestation", description = "Anji came by and asked for you. Said she was heading to the northeast ruins.\n\nOh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.", sourceObjective = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", completion = "Good, you're here.\n\nFor a while there, I was wondering if Ren would even deliver the message.", sourceObjectiveStatus = "unverified-source-field" }
quests[31241] = { id = 31241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wicked Wikkets", description = "{name} good wikket, they say...\n\n{name} help hozen, they say...\n\nNo more grookin' {name}, they say.\n\nThat ok. Look out there. Wicked wikkets fallin' like rain, ripe for the grookin'!\n\nGo, join the fun. But remember, Chief Kah Kah gets all the shinies! That's hozen rule number two.\n\n<Jeek Jeek scratches his head.>\n\nHmm, all hozen rules are number two...", progress = "Whatcha got, wikket?", completion = "Wikket grookin' makin' hozen rich with shinies!\n\n{name} makin' a good second impression. And for hozen, number two is most important!", objectives = "Collect 6 Alliance Service Medallions from Battleworn Paratroopers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31242] = { id = 31242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall Village", description = "My scouts have spotted no mogu near Mistfall Village today, but I've been hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched Che to assess the situation, but he'll most likely need your help.\n\nFind your way southwest to the village and meet Che there. Do what you can.", completion = "Leven sent me a good one today! I must thank him later.", objectives = "Speak to Che Wildwalker at Mistfall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31243] = { id = 31243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Mistfall Village", description = "Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook and Sun immediately, but I need another capable hand there as soon as possible.\n\nDon't delay. The villagers need you.", completion = "Oh, thank the celestials you're here! This is worse than we thought!", objectives = "Speak to Sun Tenderheart at Mistfall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31244] = { id = 31244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai Encampment", description = "Leven came by in quite a huff! Said something about mogu in the ruins.\n\nBest be off to find him I think. Angry Leven is not a fun Leven.", sourceObjective = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.", completion = "Glad you're here. Let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[31245] = { id = 31245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall Village", description = "Che stopped by on the way to the village and ask if I'd seen you. I told him no.\n\nYou can go see him if you want. But now you're not obligated to see him! I am so marvelously considerate, am I not?", sourceObjective = "Speak to Che Wildwalker at Mistfall Village.", completion = "Ren send you my way? He puts on playful air, but he follows through when it matters. Can't hold it against him much.", sourceObjectiveStatus = "unverified-source-field" }
quests[31246] = { id = 31246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Mistfall Village", description = "I can see smoke from the village. And it's not my fault this time!\n\nBest go and help.", sourceObjective = "Speak to Rook Stonetoe at Mistfall Village.", completion = "You come to help Rook?", sourceObjectiveStatus = "unverified-source-field" }
quests[31247] = { id = 31247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "Anji and Kun stopped by on the way to the garrison. Lovely pair, don't you think? So different, yet so devoted to each other... ah, it makes my heart swoon just thinking about it.\n\nThey asked for you by name. Maybe they want to put you through some of the training paces? I certainly hope they don't have something more naughty in mind...", completion = "Well timed. I was just about to go put some recruits through their paces, but I'd be much more eager to see what you have to offer.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31248] = { id = 31248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Guo-Lai", description = "I've instructed Anji and Kun to resume investigation of the Ruins of Guo-Lai. We have no reports of any significant mogu presence there today, but it seems to be one of their central interests here in the Vale, and want it under thorough watch consider their attack on the lake.\n\nThat's why I'm sending you as well.\n\nHead west, past the lake, to the ruins. Anji will instruct you further.", completion = "If it isn't one of my favorite paladins. Glad to have you with us.", objectives = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31249] = { id = 31249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall Village", description = "Everything I've heard suggests the village has been unaffected by the Shao-Tien offensive at the lake, but I won't take any risks.\n\nI'm dispatching you and Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.", completion = "It is strange to be dispatched away from the combat, but Leven is right in that the villagers need our protection. We cannot afford any risks.", objectives = "Speak to Che Wildwalker at Mistfall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31250] = { id = 31250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "We've taken losses from the mogu forces descending the Golden Stair and their flanking attackers at Whitepetal Lake. Our lines are thin.\n\nI'm dispatching Anji and Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like you there with them, {name}. Show them what a true {class} is made of.", completion = "Let's whip these recruits into shape.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31251] = { id = 31251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Meals Anywhere!", description = "Yeah, yeah.\n\nEveryone knows us goblins do tinkering. And explosives. And... well, ya' know, the less reputable stuff.\n\nBut what nobody knows is that I'm really a great chef! It's a hobby of mine.\n\nGather us up some meaty bits from the creatures around here, and I'll cook us up the best meals ANYWHERE!\n\nAnd I promise, I'll only use three or four percent rocket fuel.", progress = "The meaty bits, {name}? We need 'em!", completion = "You know what they say about cooking - GTL. Garnish, taste... and... laundry?", objectives = "Collect 160 Kun-Lai Meaty Bits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31252] = { id = 31252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Westwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Bo. I'll miss 'em, but they're better off with you.", completion = "You did good, bringing these guys back. We'll have 'em farming you up some food in no time!", objectives = "Return to Farmhand Bo at Westwind Rest in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31253] = { id = 31253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Eastwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Horde\". So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Ko. I'll miss 'em, but they're better off with you.", completion = "You did good, bringing these guys back. We'll have 'em farming you up some food in no time!", objectives = "Return to Farmhand Ko at Eastwind Rest in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31254] = { id = 31254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.", progress = "More strangers? This day is testing my limits.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet but as you can see we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?", objectives = "Travel through the Veiled Stair to Binan Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31255] = { id = 31255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.", progress = "More strangers? This day is testing my limits.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet, but as you can see, we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?", objectives = "Travel through the Veiled Stair to Binan Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31256] = { id = 31256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 'Em Up", description = "Lok'tar, {class}.\n\nWe've made progress, but we're going to need mobility if we want to maintain our foothold here in Kun-Lai.\n\nI don't see many worgs, kodo, or the like around here. What I do see are yaks. Our pandaren allies have said they make good mounts, so they'll have to do.\n\nGo round some up and return them here, so we can get our people riding them!", progress = "The yaks?", completion = "Well done! Well, they're plenty stubborn, I'll say that much. But they should do nicely.", objectives = "Round up 3 Wild Plains Yaks and return them to Eastwind Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31260] = { id = 31260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit Mastery: Chasheen", description = "I am totally on to another great scam!\n\nWhen I was flying overhead I saw a really ancient tigress prowling about.\n\nDo you know how much her blood would go for on the black market? Not to mention if I convince some warlocks it adds extra potency to their summoning spells or something.\n\nIf you bring me back some of her blood I will cut you in on the scam. She was prowling about on the far side of the Dojani River from here.", progress = "I thought about taking that tiger on myself but to be honest I like living...", completion = "Impressive! Can you smell the money? Here's your end.", objectives = "Collect Ancient Tiger's Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31261] = { id = 31261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Jack's Dead", description = "Gore from Captain Jack's head drips and mysteriously seeps into the ground as you examine your hard-won trophy.\n\nStrange, but no time to investigate that now. There's too much work to be done.\n\nThe chieftain of your newfound friends will doubtlessly be impressed with this proof of your grookin' skills.", completion = "Ookin' grookin, wikket!", objectives = "Bring Captain Jack's head to Chief Kah Kah at Grookin Hill.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31262] = { id = 31262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crane Mastery: Needlebeak", description = "So, now that you've got a vibe for how cranes fight, I've got a doozy for you.\n\nNeedlebeak!\n\nOr at least, that's what I'm calling him. Biggest crane I ever saw. And its beak is so sharp it's like a sword.\n\nNorthwest of here you'll find the big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the waterfall.\n\nYou bring me its beak as a trophy and I will talk you up a good game to Nesingwary.", progress = "I watched that bird stab a tiger through the face. What kind of place is this where birds are the predators for tigers?", completion = "Now THAT is a trophy. Looks intimidating. Wait... is this your blood on it?", objectives = "Acquire the Needlebeak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31265] = { id = 31265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazu's Breath", description = "Here to help, are ya? Well, first thing's first.\n\n<Arie rummages through her pockets for a moment before producing a small vial of glowing blue fluid.>\n\nHere it is! \"Mazu's Breath.\" Cap'n's own formula.\n\nWhat? You thought I'd send you out to sea without a means of breathin'? I need deckhands, not corpses!\n\nDown the hatch with it, green. This'll give you a fighting chance out there on the shelf.", progress = "No, I don't have a \"chaser!\" Just drink it!", completion = "You'll thank me later.", objectives = "Drink the Potion of Mazu's Breath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31266] = { id = 31266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Incursions", description = "We've heard reports of a group of Mogu infiltrating the coast here in Townlong. I have no idea what they are doing. Frankly, I don't care. \n\nYou've proven yourself, so we've decided to give this mission to you.\n\nWhat's going to happen is this - you're going to go, find them, and kill them.\n\nOur scouts reported the first group landed to the north, between here and Deadtalker's Plateau. Go there and wipe them out.", progress = "Why aren't they dead already?", completion = "It was just a decoy! They've moved to attack Niuzao Temple!", objectives = "Find and kill the Shan'ze Spymaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31267] = { id = 31267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistblade Destruction", description = "Korven has told me of his findings. There is an enormous amber deposit sitting at the bottom of the Lake of Stars.\n\nUnfortunately, a hostile saurok tribe lives at the edge of the lake, and revere the amber as their own.\n\nThey will not allow us to enter their territory easily.\n\nGo south to the lake. Kill the Mistblade saurok, so that we can more easily harvest the nearby amber.", completion = "Well done. With access to this amber, we shall be able to craft weapons to our cause.", objectives = "Kill 6 Mistblade Rippers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31268] = { id = 31268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Brain Work", description = "Far to the south, the swarm breeds weapons of destruction - enormous, nearly unbreakable amber scorpions.\n\nLike all other creatures, they are subject to manipulation, but unlike other creatures, they have not yet submitted to my mind control.\n\nIt appears that further research is necessary before I can dominate them for our own purposes.\n\nI must study their brains, and you must retrieve some specimens for me.\n\nTake this sonic emitter. I have found it to be quite effective against the beasts.", progress = "They continue to resist my sonic manipulation. I must understand why.", completion = "My my, this is interesting indeed. They are unlike any other brains I have seen.\n\nI will study these carefully.", objectives = "Collect 3 Amber-Encrusted Brains from Ik'thik Amberstingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31269] = { id = 31269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scale-Lord", description = "The saurok at the Lake of Stars take their orders from their Scale-Lord, a vicious, merciless leader who guards his territory fiercely.\n\nIf we can eliminate this leader, then we can gain access to the enormous amber lode beneath the lake.\n\nGo. Their leader gives his orders from his underground dwelling, at the southern edge of the lake.", completion = "Good. I am glad to hear that he is dead.", objectives = "Kill the Mistblade Scale-Lord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31270] = { id = 31270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fight Against Fear", description = "When we discovered the sha influence at Kypari Zar, I had hoped the corruption could still be cleansed.\n\nUnfortunately, the Klaxxi Council has confirmed that the sha of fear's corruption is deep-seated, and continues to spread.\n\nTo the south, I have observed some of the local wildlife consumed by an unnamed terror.\n\nThe sha can warp and twist its victims into unimaginable horrors.\n\nWe must stop the corruption before it becomes worse. Seek out the sha-infected Horrorscale Scorpids. Eliminate them.", completion = "You have purged the hills of the infected creatures? Good.\n\nThe sha is a merciless enemy. Thus must we be merciless in return.", objectives = "Kill 15 Horrorscale Scorpid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31271] = { id = 31271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Genes", description = "Far to the south, Wakener, the Empress's genemancers set about their dark experiments. (Dark yes, but not as dark as mine!)\n\nThey dissect and mutate the nearby wildlife, breeding creatures of their own design. (Their design, which will become my design!)\n\nWe must not let them succeed! (No, no! Only I am allowed such power!)\n\nTheir mutations are already being unleashed for war. Go! Destroy them at any cost!", progress = "Is it done? Are my competitio - I mean, our enemies - dead?", completion = "Yes, yes! They are dead!\n\nThank you, Wakener. Well done.", objectives = "Kill 3 Ik'thik Genemancers and 6 Ik'thik Egg-Drones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31272] = { id = 31272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infection", description = "The Empress's genemancers play with dangerous toys.\n\nTo the south, they are injecting local wildlife with pheromone-laden parasites, in an attempt to create monstrous mutations for war.\n\nCarelessly, they have allowed their parasitic worms to escape into the local ecosystem.\n\nLeft unchecked, the infection will spread from one animal to another, until we have an outbreak.\n\nI will inject you with a mild toxin. With it, you will be able to identify infected creatures.\n\nKill the carriers at once.", completion = "So the infection was spreading. You halted the spread just in time, it seems.\n\nI doubt that the genemancers will stop their outrageous experimentation, but we must continue to thwart their efforts.", objectives = "Kill 6 infected wildlife. Infected wildlife may include Bonedust Moths, Bluehide Mushan, and Mutating Scorpid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31273] = { id = 31273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Swarm", description = "PH" }
quests[31274] = { id = 31274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Raid Finder - 1st" }
quests[31275] = { id = 31275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Raid Finder - Nth" }
quests[31277] = { id = 31277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surprise Attack!", description = "Those damnable Mogu...\n\nThose scouts were a distraction! While we were hunting their spies, the main force moved on Niuzao Temple. Corrupted serpents, Mogu everywhere... this is a disaster!\n\nThankfully, Ban was able to make it past their lines with the most elite members of our order. If you can slip past, too, meet up with him. We need to put a stop to this!", completion = "Niuzao has been saved. The Mogu pushed back. And you, friend, have been found worthy of a great honor. \n\nWe shall induct you into the Shado-Pan.", objectives = "Meet up with Ban Bearheart outside Niuzao Temple in Townlong Steppes, and put a stop to the Mogu Invasion there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31278] = { id = 31278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.", sourceObjective = "Make a breadcrumb quest.", sourceObjectiveStatus = "unverified-source-field" }
quests[31279] = { id = 31279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything I Know About Cooking", description = "I'm so glad you enjoy my food. Are you interested in the recipes?  If so, you should learn them properly, from my teachers in Halfhill Market.  Everything I know about the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", progress = "You have a letter for me?", completion = "My, that's so thoughtful. I love hearing from my old students.", objectives = "Deliver the Letter to Sungshin Ironpaw. She teaches in Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31280] = { id = 31280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ways of Cooking", description = "There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.", objectives = "Learn the recipes for Charbroiled Tiger Steak, Jade Forest Fried Rice, Swirling Mist Soup, Shrimp Dumplings, Wildfowl Roast and Ginseng Tea from the masters in Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31281] = { id = 31281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So You Want to Be a Chef...", description = "You wish to be a chef? If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.\n\nIf you wish to learn, show me you can at least follow basic instructions. Learn how to slice peaches and show me what you've learned.  I have fresh pandaren peaches which I will sell to you at a token price.", progress = "Show me that you can follow instructions.", completion = "Very well.  You are capable of learning.  There is much I can teach you, and I have most of the ingredients you need to learn. Train with me.", objectives = "Learn the recipe for Sliced Peaches from the Guide to the Ways and make 5 of them for her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31282] = { id = 31282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaz'tik Tracking Quest" }
quests[31283] = { id = 31283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore Destroyed Tracking" }
quests[31284] = { id = 31284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ancient Pandaren Fishing Pole" }
quests[31285] = { id = 31285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spring Drifter", description = "Nobody really travels up the Ancient Passage on foot. That is just asking for a faceful of saurok if you are not careful.\n\nTell you what, Egg Shell and I were just about to set off upriver to Binan Village. Want a lift?", progress = "It is always good luck to have a grummle aboard when traveling through a saurok infested cave.", completion = "Wheh, we made it. Welcome to Binan Village.", objectives = "Survive a trip on the Spring Drifter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31286] = { id = 31286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robbing Robbers of Robbers", description = "Ah, a {class}. I could make good use of your skills.\n\nA convoy was struck just up the road by a band of marauding saurok. These marauders made off with some... merchandise... her ladyship, the Madam Goya, had a mind to sell.\n\nOne does not steal from her ladyship.\n\nIf you recover these items I will gladly provide you a finders fee.", progress = "Saurok are seldom this bold.", completion = "Ah, our merchandise. Madam Goya will be pleased. You have the gratitude of her ladyship.", objectives = "Recover 7 Black Market Merchandise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31287] = { id = 31287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Educating Saurok", description = "The Spring Road is under the protection of her ladyship, the esteemed Madam Goya.\n\nThe saurok of Hatescale Burrow northeast of here require \"education\" in this fact. We have warned them before but sadly they seem to have a very short memory.\n\nTravel northeast to this burrow and find their shaman leader. Eliminate him and you will have the gratitude of her ladyship. As well as an appropriate bounty.", completion = "The deed is done and a debt must be paid. Here is your reward. You have our gratitude.", objectives = "Defeat Leechfingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31288] = { id = 31288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Project: The Mogu Dynasties", description = "Ah, an explorer. Just what I could use. I am on the verge of discovering the dark secrets of the mogu.\n\nNot all of the secrets, mind you. They kept a lot of dark secrets. But I am on the verge of discovering \"a\" secret at least.\n\nIf, in your travels, you come across some fragments of the mogu past, bring them to me and I will happily reimburse you for them.", progress = "It is dangerous to forget our past.", completion = "Ah! Some fine pieces here. Very fine pieces indeed. My thanks, adventurer.", objectives = "Obtain 20 Mogu Archaeology Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31289] = { id = 31289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Project: The Pandaren Empire", description = "Ah, adventurer. You come at a most opportune time. My daughter and I are researching the history of our people and have hit a roadblock in our research.\n\nShould you come across fragments of the pandaren past, please, bring them to us here. We would benefit greatly from the additional information.", progress = "It is dangerous to forget our past.", completion = "Ah! Some fine pieces here. Very fine pieces indeed. My thanks, adventurer.", objectives = "Obtain 20 Pandaren Archaeology Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31291] = { id = 31291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Past", description = "Interested in being a Lorewalker? There is lots of digging and reading and digging and more reading.\n\nI have entire days where I stare at a broken vase trying to figure out how it goes back together.\n\nShould give it a try. Go solve one artifact of Pandaria and we will appreciate you sharing the knowledge of how you did it.", progress = "I am beginning to wonder if I'll ever get the hang of this stuff.", completion = "Wow! You got the pieces to meld together so well. The quality of this restoration is amazing.\n\nHow did you do it?", objectives = "Solve 1 artifact from Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31292] = { id = 31292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ancient Pandaren Woodcutter" }
quests[31293] = { id = 31293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", completion = "Rook can handle rest of mogu.  Thanks for help.  Good man.", objectives = "Kill 8 Shado-Tien attackers in Mistfall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31294] = { id = 31294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Guo-Lai", description = "I have my heartfelt thanks for your continued aid. Anji awaits at the Ruins of Guo-Lai to northwest.\n\nGo with courage in your heart, young {class}.", sourceObjective = "Speak to Angi Autumnlight at the Ruins of Guo-Lai.", completion = "Che sent you my way, did he?  Good to have you.\n\nThe ruins are crawling with things to be squashed.", sourceObjectiveStatus = "unverified-source-field" }
quests[31295] = { id = 31295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu within the Ruins of Guo-Lai", description = "Thank you for your help, {class}.\n\nI would enjoy your company for longer, but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, and awaits your capable hands.\n\nMay the celestials protect you, young one.", sourceObjective = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.", completion = "Good to see you.\n\nI don't know where the mogu mustered all these forces, but we need to hit them hard before they can push their advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[31296] = { id = 31296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Guo-Lai", description = "The villagers seem to be safe and the mogu are losing their foothold. We should be able to handle the rest from here. Thank you for your kind aid, {name}.\n\nAnji lead a group to investigate and clear out the Ruins of Guo-Lai to the northwest this morning. I am certain she would appreciate someone as capable as yourself. You should go to her.", sourceObjective = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", completion = "Sun is smart to send me the strong ones.  I'd accept nothing else.", sourceObjectiveStatus = "unverified-source-field" }
quests[31297] = { id = 31297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "The mogu will not be able to maintain this attack much longer. We should be able to handle it here, thanks to your kind aid.\n\nMight you be willing to find Anji at the Setting Sun Training Camp to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", completion = "You I can work with. Let's show these trainees a thing or two about how a real {class} fights.", objectives = "Speak to Anji Autumnlight at the Setting Sun Training Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31298] = { id = 31298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zouchin Village - Intro Tracking" }
quests[31299] = { id = 31299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shomi Ruins Tracking" }
quests[31300] = { id = 31300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shomi Beach Tracking" }
quests[31301] = { id = 31301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shomi Strand Tracking" }
quests[31302] = { id = 31302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for Greatness", description = "You seem to know your way around the kitchen. Demonstrate to me your skills and make me 5 bowls of rice pudding.", progress = "I believe you have the potential to be a great chef, but the proof is in the pudding, so to speak.", completion = "You are ready. You are now a zen master cook.", objectives = "Make 5 Rice Pudding and give them to the Guide to the Ways.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31303] = { id = 31303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seal is Broken", description = "<Cho looks at you in disbelief.>\n\nI... I thought Sha of this immensity were a myth - we all did. Just a story to keep our children from fighting.\n\nNo time to talk now. Those fissures - they're feeding it... it grows stronger by the moment!\n\nI must research the scrolls from my family archives. You, take this cannon and ride Mishi.\n\nYou must find a way to contain this horror that has been unleashed!", completion = "I have much research to do in very little time.\n\nThe emperor's message only warned of the unique threat war would bring to our land - this... Sha.\n\nSadly, the time to heed his message has passed. And as for how to bring an end to the crisis, the Emperor's Omen is silent.", objectives = "Seal 12 Sha Fissures to banish the Sha of Doubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31304] = { id = 31304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Kafa Press" }
quests[31305] = { id = 31305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Grill", description = "If you wish to cook foods that make you stronger, go seek the Master of the Grill.  Cook him a skewered peanut chicken to show him that you have the basics.", objectives = "Make a Skewered Peanut Chicken and give it to the Master of the Grill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31306] = { id = 31306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only <his/her> thoughts. <He/She> will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", completion = "Ah, you made it, and you honored the shrines.\n\nI knew you could handle it.", objectives = "Brave the path of Seeker's Folly to find Lorewalker Cho, stopping to reflect at the three shrines along the way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31307] = { id = 31307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Jade Infused Blade" }
quests[31308] = { id = 31308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Ropes", description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out into the forest and pick a fight with a battle pet.  Make sure to use your Track Pets skill so you can see pets you can fight on the minimap.  Come back to me after you have won and I will continue your training. Good luck!", completion = "Nice work, {name}!  You're better with those pets than I thought!", objectives = "Win a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31309] = { id = 31309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On The Mend", description = "Now that you have won a battle, we need to heal up your pets so they can fight another day!  Visit Erma, our local stable master, to heal and revive your pets.", progress = "Are your pets feeling better?", completion = "Now those look like some healthy pets, {name}.  Remember, you can heal and revive your entire collection of pets at any time by visiting a stable master.", objectives = "Heal your pets to full health by visiting Erma the Stable Master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31310] = { id = 31310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interrogation Tracking" }
quests[31311] = { id = 31311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Way of the Grill", description = "The Pandaren Way of the Grill produces foods that increase your physical strength. Bring some raw tiger steaks to the Master of the Grill, and he will teach you what you can do with them. There are many tigers in the Jade Forest and the Krasarang Wilds, but you can also find them in other places.", progress = "If you wish to learn the Way of the Grill, bring me some raw tiger steaks.", completion = "Good cuts.", objectives = "Bring 5 Raw Tiger Steaks to the Master of the Grill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31312] = { id = 31312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Map", description = "The old, faded leather is falling apart, but still legible.\n\nScrawled on it is some kind of map, and the following lines:\n\n\nDeep in the valley where four winds blow,\nThe maiden laughs behind her golden fan.\nAt the feet of her ancestors' stair,\nShe whispers secrets into the echoing dark.", completion = "Whoa! I think you found it, {name}! You found the map to Old Man Thistle treasure!", objectives = "Show the map to Fish Fellreed at Cattail Lake or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31313] = { id = 31313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just A Folk Story", description = "What!?! This don't make any sense! <Fish's face falls.>\n\nWhat's this mumber jumber about a maiden and an ancestor and a buncha stairs?\n\nI can't make any reason outta this, can you?\n\nWell, there are lotsa folks 'round here who're much older than you and me, {name}.\n\nCan you go talk to the folks in Halfhill? I betcha they might know somethin'!", completion = "Of course! It makes perfect sense. So the location of the treasure must be where the lake meets the mountains!", objectives = "Speak to Grainsorter Pei, Stonecarver Mac, Mama Min, and Old Man Whitewhiskers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
